CREATE MATERIALIZED VIEW non_leaf_63 AS
SELECT cn.id AS cn_id, cn.name AS cn_name, cn.country_code AS cn_country_code, cn.imdb_id AS cn_imdb_id, cn.name_pcode_nf AS cn_name_pcode_nf, cn.md5sum AS cn_md5sum, mc.id AS mc_id, mc.movie_id AS mc_movie_id, mc.company_id AS mc_company_id, mc.company_type_id AS mc_company_type_id, mc.note AS mc_note, n.id AS n_id, n.name AS n_name, n.imdb_index AS n_imdb_index, n.imdb_id AS n_imdb_id, n.gender AS n_gender, n.name_pcode_cf AS n_name_pcode_cf, n.name_pcode_nf AS n_name_pcode_nf, n.surname_pcode AS n_surname_pcode, n.md5sum AS n_md5sum, ci.id AS ci_id, ci.person_id AS ci_person_id, ci.movie_id AS ci_movie_id, ci.person_role_id AS ci_person_role_id, ci.note AS ci_note, ci.nr_order AS ci_nr_order, ci.role_id AS ci_role_id, rt.id AS rt_id, rt.role AS rt_role, mk.id AS mk_id, mk.movie_id AS mk_movie_id, mk.keyword_id AS mk_keyword_id, t.id AS t_id, t.title AS t_title, t.imdb_index AS t_imdb_index, t.kind_id AS t_kind_id, t.production_year AS t_production_year, t.imdb_id AS t_imdb_id, t.phonetic_code AS t_phonetic_code, t.episode_of_id AS t_episode_of_id, t.season_nr AS t_season_nr, t.episode_nr AS t_episode_nr, t.series_years AS t_series_years, t.md5sum AS t_md5sum, kt.id AS kt_id, kt.kind AS kt_kind
FROM company_name AS cn, movie_companies AS mc, name AS n, cast_info AS ci, role_type AS rt, movie_keyword AS mk, title AS t, kind_type AS kt
WHERE cn.id = mc.company_id AND cn.name ~~* '%h%' AND mc.movie_id = t.id AND n.id = ci.person_id AND n.surname_pcode ~~* '%k34%' AND ci.movie_id = t.id AND ci.role_id = rt.id AND rt.role IN ('actor', 'actress', 'cinematographer', 'composer', 'costume designer', 'director', 'editor', 'miscellaneous crew', 'producer', 'writer') AND t.kind_id = kt.id AND mk.movie_id = t.id AND t.title ~~* '%ho%' AND kt.kind IN ('episode', 'tv movie', 'tv series', 'video game', 'video movie');